package com.localcanvas.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;import java.util.concurrent.*;
public class MainActivity extends Activity{
 LinearLayout c;EditText p,n;ImageView image;ProgressBar bar;Button go,stop;ExecutorService ex=Executors.newSingleThreadExecutor();volatile boolean busy;File model;
 TextView t(String s){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(16);v.setPadding(20,16,20,16);return v;}
 public void onCreate(Bundle b){super.onCreate(b);screen();}
 void screen(){c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackgroundColor(Color.rgb(11,11,18));c.addView(t("LocalCanvas · 실제 로컬 생성"));p=new EditText(this);p.setHint("프롬프트");p.setTextColor(Color.WHITE);c.addView(p);n=new EditText(this);n.setHint("네거티브 프롬프트");n.setTextColor(Color.WHITE);c.addView(n);image=new ImageView(this);image.setAdjustViewBounds(true);c.addView(image);bar=new ProgressBar(this);bar.setVisibility(View.GONE);c.addView(bar);go=new Button(this);go.setText("실제 생성");go.setOnClickListener(v->start());c.addView(go);stop=new Button(this);stop.setText("생성 중단");stop.setVisibility(View.GONE);stop.setOnClickListener(v->NativeEngine.nativeCancel());c.addView(stop);Button pick=new Button(this);pick.setText("모델 파일 선택");pick.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);});c.addView(pick);setContentView(c);}
 void start(){if(busy)return;if(!NativeEngine.isNativeLibraryLoaded()||!NativeEngine.nativeIsAvailable()){Toast.makeText(this,"네이티브 엔진이 없는 APK입니다.",Toast.LENGTH_LONG).show();return;}if(model==null){Toast.makeText(this,"먼저 모델 파일을 선택하세요.",Toast.LENGTH_LONG).show();return;}if(p.getText().toString().trim().isEmpty())return;busy=true;go.setEnabled(false);stop.setVisibility(View.VISIBLE);bar.setVisibility(View.VISIBLE);String prompt=p.getText().toString(),neg=n.getText().toString();ex.submit(()->{try{Bitmap b=NativeEngine.nativeGenerate(model.getAbsolutePath(),prompt,neg,512,512,20,7,System.currentTimeMillis(),4);runOnUiThread(()->{image.setImageBitmap(b);save(b);});}catch(Throwable e){runOnUiThread(()->Toast.makeText(this,"생성 실패: "+e.getMessage(),Toast.LENGTH_LONG).show());}finally{runOnUiThread(()->{busy=false;go.setEnabled(true);stop.setVisibility(View.GONE);bar.setVisibility(View.GONE);});}});}
 void save(Bitmap b){try{ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"LocalCanvas_"+System.currentTimeMillis()+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/LocalCanvas");Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(u!=null)try(OutputStream o=getContentResolver().openOutputStream(u)){b.compress(Bitmap.CompressFormat.PNG,100,o);}}catch(Exception ignored){}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c==RESULT_OK&&d!=null){String s=d.getData().toString();model=new File(getFilesDir(),"selected.model");try(InputStream i=getContentResolver().openInputStream(d.getData());OutputStream o=new FileOutputStream(model)){byte[]b=new byte[1048576];int z;while((z=i.read(b))>0)o.write(b,0,z);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}}
 protected void onDestroy(){if(busy)NativeEngine.nativeCancel();ex.shutdownNow();super.onDestroy();}
}  
